const MAP_SOURCE_EXTENT = {
  x: 16,
  y: 7.9,
  width: 1148,
  height: 574,
};

// The Natural Earth SVG was generated with an equirectangular projection.
// Project every event and station through the exact same source extent and
// SVG transform as the land path so markers cannot drift away from geography.
const projectLonLat = (longitude: number, latitude: number) => {
  const sourceX =
    MAP_SOURCE_EXTENT.x +
    ((longitude + 180) / 360) * MAP_SOURCE_EXTENT.width;
  const sourceY =
    MAP_SOURCE_EXTENT.y +
    ((90 - latitude) / 180) * MAP_SOURCE_EXTENT.height;

  return {
    x: MAP_TRANSFORM.x + sourceX * MAP_TRANSFORM.scale,
    y: MAP_TRANSFORM.y + sourceY * MAP_TRANSFORM.scale,
  };
};

