const clamp01 = (value: number) => Math.max(0, Math.min(1, value));
const mix = (from: number, to: number, progress: number) =>
  from + (to - from) * progress;
const smooth = (value: number) =>
  Easing.inOut(Easing.cubic)(clamp01(value));
const outCubic = (value: number) =>
  Easing.out(Easing.cubic)(clamp01(value));
const smoothRange = (value: number, start: number, end: number) =>
  smooth((value - start) / Math.max(0.0001, end - start));

