const waveformPath = (
  width: number,
  height: number,
  loopPhase: number,
  intensity: number,
) => {
  const points = 112;
  const center = height / 2;
  const theta = loopPhase * Math.PI * 2;
  const amplitude = 5 + intensity * 1.9;
  let path = "";

  for (let i = 0; i < points; i++) {
    const x = (i / (points - 1)) * width;
    const envelope =
      0.16 +
      0.84 *
        Math.exp(
          -Math.pow((i - points * (0.42 + 0.06 * Math.sin(theta))) / 21, 2),
        );
    const signal =
      Math.sin(i * 0.63 + theta * 5) * 0.55 +
      Math.sin(i * 1.47 - theta * 3) * 0.24 +
      Math.sin(i * 0.21 + theta * 7) * 0.21;
    const y = center + signal * envelope * amplitude;
    path += `${i === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`;
  }
  return path;
};

